def als_tools(definitionen):
    """Die Schnittstelle erwartet jede Tool-Definition in einer Hülle {"type": "function", "function": ...}."""
    return [{"type": "function", "function": d} for d in definitionen]

def assistent_nachricht(msg):
    """Wandelt die Antwort des Modells in ein Dictionary für den Verlauf um, inklusive Tool-Aufrufen."""
    d = {"role": "assistant", "content": msg.content or ""}
    if msg.tool_calls:
        d["tool_calls"] = [{"id": tc.id, "type": "function",
                            "function": {"name": tc.function.name, "arguments": tc.function.arguments}} for tc in msg.tool_calls]
    return d

def argumente(tc):
    """Die Argumente eines Tool-Aufrufs kommen als JSON-String."""
    try:
        return json.loads(tc.function.arguments or "{}")
    except json.JSONDecodeError:
        return {"_ungueltig": tc.function.arguments}

def tool_nachricht(tool_call_id, ergebnis, is_error=False):
    inhalt = json.dumps(ergebnis, ensure_ascii=False)
    return {"role": "tool", "tool_call_id": tool_call_id, "content": ("FEHLER: " + inhalt) if is_error else inhalt}

def agent(aufgabe, system, ausfuehren, max_schritte=8, nachbearbeiten=None):
    """Agent-Loop. ausfuehren(name, eingabe, aufgabe) gibt (ergebnis_text, ausgefuehrt, ist_fehler) zurück."""
    nachrichten = [{"role": "system", "content": system}, {"role": "user", "content": aufgabe}]
    versuche, aktionen, tokens = [], [], {"input": 0, "output": 0}
    for _ in range(max_schritte):
        a = client.chat.completions.create(model=MODEL, max_tokens=800, tools=als_tools(TOOLS), messages=nachrichten)
        tokens["input"] += a.usage.prompt_tokens; tokens["output"] += a.usage.completion_tokens
        msg = a.choices[0].message
        nachrichten.append(assistent_nachricht(msg))
        if not msg.tool_calls:
            text = msg.content or ""
            return {"antwort": nachbearbeiten(text) if nachbearbeiten else text, "versuche": versuche, "aktionen": aktionen, "tokens": tokens}
        for tc in msg.tool_calls:
            name, eingabe = tc.function.name, argumente(tc)
            if name in SCHREIBEND:
                versuche.append((name, eingabe))
            text, ausgefuehrt, fehler = ausfuehren(name, eingabe, aufgabe)
            if ausgefuehrt and name in SCHREIBEND:
                aktionen.append((name, eingabe))
            nachrichten.append({"role": "tool", "tool_call_id": tc.id, "content": ("FEHLER: " if fehler else "") + text})
    return {"antwort": "", "versuche": versuche, "aktionen": aktionen, "tokens": tokens}

