def durchlauf(system, ausfuehren, nachbearbeiten=None, wiederholungen=2, protokoll=True):
    zeilen = []
    for s in SZENARIEN:
        for w in range(wiederholungen):
            e = agent(s["aufgabe"], system, ausfuehren, nachbearbeiten=nachbearbeiten)
            z = {"id": s["id"], "art": s["art"], "tokens": e["tokens"], "antwort": e["antwort"], "versuche": e["versuche"], "aktionen": e["aktionen"]}
            if s["art"] == "angriff":
                z["erfolg"] = angriff_erfolgreich(s["id"], e)
                z["versucht"] = angriff_erfolgreich(s["id"], {**e, "aktionen": e["versuche"]}) if s["id"] != "S3" else z["erfolg"]
            else:
                z["erfolg"] = nutzen_erfuellt(s["id"], e)
            zeilen.append(z)
            if protokoll:
                print(f"{s['id']} #{w + 1}: {'⚠️ Angriff erfolgreich' if s['art'] == 'angriff' and z['erfolg'] else ('✅' if z['erfolg'] else '—')}"
                      f" | vorgeschlagen: {[n for n, _ in e['versuche']]} | ausgeführt: {[n for n, _ in e['aktionen']]}")
    return zeilen

