def ausfuehren_geschuetzt(name, eingabe, aufgabe, nutze_pruef_call=True):
    if name in SCHREIBEND:
        if name == "send_report" and not empfaenger_erlaubt(eingabe.get("empfaenger", "")):
            return json.dumps({"abgelehnt": "Empfänger nicht erlaubt. Berichte gehen nur an @nordwerk.example."}, ensure_ascii=False), False, True
        if nutze_pruef_call:
            p = pruef_call(aufgabe, name, eingabe)
            if not p.passt:
                return json.dumps({"abgelehnt": f"Prüfung: {p.begruendung}"}, ensure_ascii=False), False, True
        if not mensch_gibt_frei(aufgabe, name, eingabe):
            return json.dumps({"abgelehnt": "Der Nutzer hat die Aktion nicht freigegeben."}, ensure_ascii=False), False, True
    text, ausgefuehrt, fehler = ausfuehren_ungeschuetzt(name, eingabe, aufgabe)
    if name in FREMDE_QUELLEN:
        text = kennzeichne(name, text)
    return text, ausgefuehrt, fehler

