LOGDATEI = "agent_log.jsonl"

def protokollierter_aufruf(**kwargs):
    t0 = time.time()
    eintrag = {"zeit": datetime.datetime.now().isoformat(timespec="seconds"), "status": "unbekannt"}
    try:
        antwort = client.chat.completions.create(**kwargs)
        eintrag = {"zeit": datetime.datetime.now().isoformat(timespec="seconds"), "modell": kwargs["model"], "status": "ok",
                   "finish_reason": antwort.choices[0].finish_reason, "input": antwort.usage.prompt_tokens, "output": antwort.usage.completion_tokens,
                   "dauer_s": round(time.time() - t0, 2), "request_id": getattr(antwort, "_request_id", None)}
        return antwort
    except openai.RateLimitError as e:
        eintrag = {"zeit": datetime.datetime.now().isoformat(timespec="seconds"), "status": "rate_limit", "fehler": str(e)[:200]}
        raise
    except openai.APIStatusError as e:
        eintrag = {"zeit": datetime.datetime.now().isoformat(timespec="seconds"), "status": f"http_{e.status_code}", "fehler": str(e)[:200]}
        raise
    finally:
        with open(LOGDATEI, "a", encoding="utf-8") as f:
            f.write(json.dumps(eintrag, ensure_ascii=False) + "\n")

protokollierter_aufruf(model=MODEL, max_tokens=50, messages=[{"role": "user", "content": "Sag kurz Hallo."}])
